import ast, glob, sys

NET = ("urllib", "http", "socket")
STDLIB_OK = None


def tree_of(path):
    return ast.parse(open(path, encoding="utf-8").read(), path)


def imports(path):
    out = []
    for n in ast.walk(tree_of(path)):
        if isinstance(n, ast.Import):
            out += [a.name for a in n.names]
        elif isinstance(n, ast.ImportFrom):
            out.append("." * n.level + (n.module or ""))
    return out


def top(m):
    return m.lstrip(".").split(".")[0]


def classes(path):
    return [n.name for n in ast.walk(tree_of(path))
            if isinstance(n, ast.ClassDef)]


def functions(path):
    return {n.name: n for n in ast.walk(tree_of(path))
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}


def methods(path, cls):
    for n in ast.walk(tree_of(path)):
        if isinstance(n, ast.ClassDef) and n.name == cls:
            return {m.name: m for m in n.body
                    if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))}
    return {}


def tests_of(path):
    """Every test_* function, duplicates included (a dict would eat them)."""
    return [n.name for n in ast.walk(tree_of(path))
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
            and n.name.startswith("test_")]


def check_core():
    """No Network In Core, one sqlite3, and the one matplotlib exception."""
    out = []
    for p in sorted(glob.glob("ethsc/*.py")):
        names = imports(p)
        if p != "ethsc/rpc.py":
            out += ["No Network In Core: %s imports %s" % (p, m)
                    for m in names if top(m) in NET]
        if p != "ethsc/store.py":
            out += ["%s imports sqlite3 directly; use ethsc.store.Store" % p
                    for m in names if top(m) == "sqlite3"]
        if p != "ethsc/charts.py":
            out += ["Stdlib Only: %s imports %s; only ethsc/charts.py may, "
                    "and every number is computed by the standard library"
                    % (p, m)
                    for m in names
                    if top(m) in ("matplotlib", "numpy", "pandas", "scipy",
                                  "seaborn", "plotly")]
        else:
            out += ["%s imports %s; the drawing layer takes matplotlib and "
                    "nothing else" % (p, m)
                    for m in names
                    if top(m) in ("numpy", "pandas", "scipy", "seaborn",
                                  "plotly")]
    return out


def check_handlers(path):
    out = []
    for n in ast.walk(tree_of(path)):
        if not isinstance(n, ast.ExceptHandler):
            continue
        if n.type is None:
            out.append("%s line %d: a bare except; name the exception"
                       % (path, n.lineno))
            continue
        names = [x.id for x in ast.walk(n.type) if isinstance(x, ast.Name)]
        if "BaseException" in names:
            out.append("%s line %d: except BaseException would swallow "
                       "SystemExit" % (path, n.lineno))
    return out


def check_private(path, why):
    out = []
    for n in ast.walk(tree_of(path)):
        if isinstance(n, ast.Attribute) and n.attr.startswith("_") \
                and not n.attr.startswith("__"):
            out.append("%s line %d reads a private attribute .%s; %s"
                       % (path, n.lineno, n.attr, why))
    return out


HELPER_FUNCTIONS = ("load_hex", "block_codes", "block_receipts",
                    "temp_store")
HELPER_CLASSES = ("FakeTransport", "FakeRpc", "InterruptAfter")


def check_helpers_additive(path="tests/helpers.py"):
    """tests/helpers.py is additive for every card that owns it.

    Names, not counts: the run of 29.09 lost three functions in one
    variant and the class InterruptAfter in another, and the class went
    unnoticed until pytest failed to collect two unrelated files.
    """
    out = []
    have_fns = functions(path)
    have_cls = classes(path)
    for name in HELPER_FUNCTIONS:
        if name not in have_fns:
            out.append("%s lost the function %s; this file is additive -- "
                       "every name that was there stays, you only add"
                       % (path, name))
    for name in HELPER_CLASSES:
        if name not in have_cls:
            out.append("%s lost the class %s; this file is additive -- every "
                       "name that was there stays, you only add. %s is "
                       "imported by tests/test_cli.py and "
                       "tests/test_cli_examples.py, which stop collecting "
                       "without it" % (path, name, name))
    for m in imports(path):
        if top(m) in NET:
            out.append("%s imports %s: the stubs stay offline" % (path, m))
    if tests_of(path):
        out.append("%s defines test_* functions; pytest would collect them"
                   % path)
    return out


def check_smoke(path, low, high):
    out = []
    names = tests_of(path)
    if len(names) > high:
        out.append("%s has %d test_* functions; at most %d -- its own tests "
                   "are smoke, the probe judges completeness"
                   % (path, len(names), high))
    if len(names) < low:
        out.append("%s has %d test_* functions; the %d that were there stay"
                   % (path, len(names), low))
    fakes = [c for c in classes(path) if c.startswith("Fake")]
    if fakes:
        out.append("%s defines Fake* classes (%s); tests/helpers.py holds the "
                   "stubs of this project" % (path, ", ".join(sorted(fakes))))
    for m in imports(path):
        if top(m) in NET:
            out.append("%s imports %s: tests stay offline" % (path, m))
    return out


bad = []

bad += check_core()
bad += check_helpers_additive()

path = "tests/test_cli_examples.py"
names = tests_of(path)
if len(names) < 18:
    bad.append("%s has %d test_* functions; the fourteen command examples and the four "
               "risk examples make eighteen: the risk listing, its two "
               "--flag runs, the flag column on cluster and on similar"
               % (path, len(names)))
if len(names) > 30:
    bad.append("%s has %d test_* functions; the risk examples need no more"
               % (path, len(names)))
_src = open(path, encoding="utf-8").read()
for _label, _spell in (("the risk listing count", ("34",)),
                       ("the selfdestruct address",
                        ("0xfeeeeee44046c3f61a8cc081e0918ef0de0a7ffc",)),
                       ("the mutable_delegatecall flag",
                        ("mutable_delegatecall",))):
    if not any(_s in _src for _s in _spell):
        bad.append("%s never mentions %s (%r); every risk example is pinned "
                   "by its value" % (path, _label, list(_spell)))
fakes = [c for c in classes(path) if c.startswith("Fake")]
if fakes:
    bad.append("%s defines Fake* classes (%s); tests/helpers.py holds the "
               "stubs" % (path, ", ".join(sorted(fakes))))
if "helpers" not in " ".join(imports(path)):
    bad.append("%s must keep importing tests.helpers" % path)
for m in imports(path):
    if top(m) in NET:
        bad.append("%s imports %s: tests stay offline" % (path, m))

print("\n".join("guard: " + b for b in bad) if bad else "guard: ast OK")
sys.exit(1 if bad else 0)
PY
 pyt tests/test_cli_examples.py -q --tb=short
